with matched_keys as (select status, plan from subscriptions except distinct select status, plan from subscriptions where end_date between '2023-10-01' and '2024-04-29'), kept_rows as (select s.* from subscriptions s inner join matched_keys k on s.status = k.status and s.plan = k.plan) select s.id, s.customer_id, s.plan, s.end_date, s.monthly_fee, s.status, case when status rlike '^(ACTIVE|EXPIRED)$' then 'PRIORITY' else 'GROUP_B' end as status_zone, (select sum(o2.amount) from orders o2 where o2.customer_id = s.customer_id) as sum_order_amount from kept_rows s order by id asc;
